PATCH=''
import base64,csv,glob,hashlib,json,os,shutil,statistics,subprocess,sys,time
from collections import Counter
W='/kaggle/working'; R='/kaggle/tmp/foal'
os.makedirs('/kaggle/tmp',exist_ok=True)
def sh(c,**k):
    print('$',c,flush=True); return subprocess.run(c,shell=True,check=True,**k)
sh('pip install -q torch==2.7.1 torchvision==0.22.1 --index-url https://download.pytorch.org/whl/cu126')
sh('pip install -q timm==1.0.30 datasets wandb pyyaml pytest')
sh(f'git clone -q https://github.com/caoban123/F-OAL.git {R}')
os.chdir(R)
sh('git checkout -q e917492')
open('/kaggle/tmp/a.patch','wb').write(base64.b64decode(PATCH))
sh('git apply --whitespace=nowarn /kaggle/tmp/a.patch')
sh('git status --short')
import torch
print('GPU',torch.cuda.get_device_name(0),torch.__version__,flush=True)
subprocess.run('python -m pytest -q tests/test_dataset_adapters.py -k aircraft',shell=True)
os.environ.update(WANDB_MODE='offline',WANDB_DIR=W,WANDB_BASE_URL='https://api.forge.coreweave.com',PYTHONPATH=R)
CFG={'a0_full':62.2,'a1_without_ff':60.9,'a2_without_sp':58.7,'a3_without_both':56.0}
rows=[]
def run(name,seed,extra_cfg=None):
    cfg=extra_cfg or f'configs/aircraft/aircraft_{name}.yaml'
    rn=f'aircraft_{name}_seed{seed}'; out=f'{W}/runs/{rn}'
    t=time.time()
    sh(f'python scripts/train.py --config {cfg} --seed {seed} --class-order-seed {seed} --projection-seed {seed} --stream-seed {seed} '
       f'--feature-cache-dir /kaggle/tmp/cache --run-name {rn} --output-dir {out} --wandb --wandb-offline --wandb-group aircraft_table4_ablation --wandb-tags aircraft,table4,seed{seed}',stdout=subprocess.DEVNULL)
    m=json.load(open(f'{out}/metrics.json')); m.pop('task_matrix',None)
    r={'name':name,'seed':seed,'sec':round(time.time()-t),**{k:v for k,v in m.items() if isinstance(v,(int,float))}}
    rows.append(r); print(json.dumps(r),flush=True)
    for f in glob.glob(f'{out}/**/*.pt',recursive=True): os.remove(f)
    csv_rows=sorted({k for x in rows for k in x})
    with open(f'{W}/summary.csv','w',newline='') as f:
        w=csv.DictWriter(f,csv_rows); w.writeheader(); w.writerows(rows)
for seed in (42,123,2026):
    for name in CFG: run(name,seed)
import yaml
c=yaml.safe_load(open('configs/aircraft/aircraft_a0_full.yaml')); c['dataset']['interpolation']='bilinear'
yaml.safe_dump(c,open('/kaggle/tmp/bil.yaml','w')); run('a0_full_bilinear',42,'/kaggle/tmp/bil.yaml')
for name,paper in CFG.items():
    v=[r['average_incremental_accuracy']*100 for r in rows if r['name']==name]
    print(name,'paper',paper,'ours',[round(x,2) for x in v],'mean',round(statistics.mean(v),2),'std',round(statistics.stdev(v),2),flush=True)
try:
    from datasets import load_dataset
    from torchvision.datasets import FGVCAircraft
    from PIL import Image
    tv=FGVCAircraft('/kaggle/tmp/tv',split='train',annotation_level='variant',download=True)
    a=Counter((tv.classes[l],hashlib.md5(Image.open(f).convert('RGB').tobytes()).hexdigest()) for f,l in zip(tv._image_files,tv._labels))
    hf=load_dataset('Multimodal-Fatima/FGVC_Aircraft_train',split='train').select_columns(['image','label'])
    n=hf.features['label'].names
    b=Counter((n[x['label']],hashlib.md5(x['image'].convert('RGB').tobytes()).hexdigest()) for x in hf)
    print('CROSSCHECK tv',len(tv),'hf',len(hf),'same(label+pixels)',sum((a&b).values()),flush=True)
except Exception as e:
    print('CROSSCHECK failed',repr(e),flush=True)
print('DONE',flush=True)
